update standard_sport_market_category 
 set name_code = CONCAT(UNIX_TIMESTAMP(), CEILING(RAND()*900000000+100000000)), 
 desc_name_code = CONCAT(UNIX_TIMESTAMP(), CEILING(RAND()*900000000+100000000)) 
 where market_category_id = 41;*/
 
delete from i18n_market_category where name_code in (select name_code from standard_sport_market_category where market_category_id = 41);
select 
	sport_t.name_code,
	i18t.flag,
	i18t.data_source_code,
	CASE		
		WHEN i18t.language_type = 'pb' THEN
		'pt' 
		WHEN i18t.language_type = 'it' THEN
		'it_IT' 
		WHEN i18t.language_type = 'de' THEN
		'de_DE' 
		WHEN i18t.language_type = 'fr' THEN
		'fr_FR' ELSE i18t.language_type 
	END,
	 i18t.text,
	i18t.remark,
	unix_timestamp(now()) * 1000,	
	unix_timestamp(	now()) * 1000
from standard_sport_market_category sport_t
INNER JOIN standard_market_category st on st.id = sport_t.market_category_id
INNER JOIN i18n_market_category i18t ON i18t.name_code = st.name_code 
where st.id = 41;
delete from i18n_market_category where name_code in (select desc_name_code from standard_sport_market_category where market_category_id = 41);
select 
	sport_t.desc_name_code,
	i18t.flag,
	i18t.data_source_code,
	CASE		
		WHEN i18t.language_type = 'pb' THEN
		'pt' 
		WHEN i18t.language_type = 'it' THEN
		'it_IT' 
		WHEN i18t.language_type = 'de' THEN
		'de_DE' 
		WHEN i18t.language_type = 'fr' THEN
		'fr_FR' ELSE i18t.language_type 
	END,
	i18t.text,
	i18t.remark,
	unix_timestamp(now()) * 1000,	
	unix_timestamp(	now()) * 1000
from standard_sport_market_category sport_t
INNER JOIN standard_market_category st on st.id = sport_t.market_category_id
INNER JOIN i18n_market_category i18t ON i18t.name_code = st.name_code 
where st.id = 41;

